// Pictures of what each node kind does, for the palette and the node panel:
// a ring for kinds that make a field (sampled LED colours, drawn here by the
// same `renderRing` that makes an agent's snapshot, so they are crisp at any
// size and cost a few KB each) and a trace for kinds that make a number or an
// event. The data is generated by `scripts/thumbnails.ts` into
// `thumbs.gen.ts`, loaded on first use as its own chunk.

import { useEffect, useRef, useState } from "react";
import { renderRing } from "../runtime/ring";

/** One curve over the trace's time span: bytes 0..255, base64. */
export type TraceLine = string;

export interface TraceThumb {
  /** The node's output, scaled to 0..1 over the trace (absent for a kind
   * whose shown output is an event). */
  out?: TraceLine;
  /** Where the shown output fired, as fractions of the time span. */
  ticks?: number[];
  /** What drives it in the showcase patch, drawn faintly behind. */
  in?: TraceLine;
  inTicks?: number[];
}

export interface ThumbData {
  /** Ring layout of every picture: `spokes × samples` LEDs, RGB, spoke-major,
   * LED 0 at the outer end (as `renderRing` takes them). */
  spokes: number;
  samples: number;
  innerOverOuter: number;
  /** Seconds of patch time each trace spans. */
  traceSeconds: number;
  rings: Record<string, string>;
  traces: Record<string, TraceThumb>;
}

/** Kinds whose icon says it all: no picture, no trace (a lone Output, a
 * note, a constant). Everything else has one; `thumbs.test.ts` holds
 * `thumbs.gen.ts` to it. */
export const ICON_ONLY: ReadonlySet<string> = new Set(["output", "note", "code", "subpatch", "slider", "globals"]);

let loading: Promise<ThumbData | null> | null = null;
let loaded: ThumbData | null = null;

function loadThumbs(): Promise<ThumbData | null> {
  loading ??= import("./thumbs.gen")
    .then((m) => (loaded = m.THUMBS))
    .catch(() => null);
  return loading;
}

/** The thumbnail data, once loaded (null until then, or if it fails). */
export function useThumbs(): ThumbData | null {
  const [data, setData] = useState(loaded);
  useEffect(() => {
    if (data) return;
    let live = true;
    void loadThumbs().then((d) => live && setData(d));
    return () => {
      live = false;
    };
  }, [data]);
  return data;
}

function bytes(b64: string): Uint8Array {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

/** Whether `kind` has a picture or a trace. */
export function hasThumb(data: ThumbData | null, kind: string): boolean {
  return !!data && (kind in data.rings || kind in data.traces);
}

const ringCache = new Map<string, ImageData>();

/** A kind's ring picture, `size` CSS pixels square. */
export function RingThumb({ data, kind, size }: { data: ThumbData; kind: string; size: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current;
    const rgb = data.rings[kind];
    if (!canvas || !rgb) return;
    const px = Math.round(size * Math.min(window.devicePixelRatio || 1, 2));
    const key = `${kind}@${px}`;
    let image = ringCache.get(key);
    if (!image) {
      const geometry = { spokes: data.spokes, pixels: data.samples, innerOverOuter: data.innerOverOuter };
      const pic = renderRing(bytes(rgb), geometry, { size: px });
      image = new ImageData(new Uint8ClampedArray(pic.rgba.buffer as ArrayBuffer), pic.width, pic.height);
      ringCache.set(key, image);
    }
    canvas.width = px;
    canvas.height = px;
    canvas.getContext("2d")?.putImageData(image, 0, 0);
  }, [data, kind, size]);
  return <canvas ref={ref} className="thumb-ring" style={{ width: size, height: size }} aria-hidden="true" />;
}

function path(line: TraceLine, w: number, h: number, pad: number): string {
  const v = bytes(line);
  let d = "";
  for (let i = 0; i < v.length; i++) {
    const x = (i / Math.max(v.length - 1, 1)) * w;
    const y = pad + (1 - v[i]! / 255) * (h - 2 * pad);
    d += `${i ? "L" : "M"}${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  return d;
}

/** A kind's trace: its output over a few seconds of the showcase patch,
 * with what drives it faint behind. */
export function TraceThumbView({
  trace,
  width,
  height,
}: {
  trace: TraceThumb;
  width: number;
  height: number;
}) {
  const pad = 2;
  const ticks = (at: number[] | undefined, cls: string) =>
    at?.map((t, i) => <line key={`${cls}${i}`} className={cls} x1={t * width} x2={t * width} y1={height * 0.25} y2={height} />);
  return (
    <svg className="thumb-trace" width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-hidden="true">
      {trace.in && <path className="trace-in" d={path(trace.in, width, height, pad)} />}
      {ticks(trace.inTicks, "trace-in-tick")}
      {trace.out && <path className="trace-out" d={path(trace.out, width, height, pad)} />}
      {ticks(trace.ticks, "trace-tick")}
    </svg>
  );
}
